def purge_extraction_results(
    apps: StateApps, schema_editor: BaseDatabaseSchemaEditor
) -> None:
    """Delete referenced result files and retire the extraction content type."""
    database = schema_editor.connection.alias
    extraction = apps.get_model("bloomerp", "FileExtraction")
    storage = extraction._meta.get_field("result").storage
    result_names = (
        extraction.objects.using(database)
        .filter(result__startswith="bloomerp/extractions/")
        .order_by()
        .values_list("result", flat=True)
        .distinct()
    )
    for name in result_names.iterator():
        try:
            storage.delete(name)
        except FileNotFoundError:
            continue

    content_type = apps.get_model("contenttypes", "ContentType")
    content_type.objects.using(database).filter(
        app_label="bloomerp", model="fileextraction"
    ).delete()


